// The one entry this run works on (D8), chosen from the sheet alone so the asset read below
// can be filtered on it. QUEUE first, then the oldest mid-flight claim: a run that died while
// Slack waited is picked up before a new row is started, so a stuck entry cannot starve behind
// fresh work. Half-finished work is never inferred from whichever field looks untouched - that
// is what select_article_to_queue decides next, from the asset rows.
const rows = $input.all()
  .map((i) => ({ ...i.json, row_number: Number(i.json.row_number || 0) }))
  .filter((r) => r.row_number && String(r.ENTRY_ID || '').trim());
const status = (r) => String(r.STATUS || '').trim().toUpperCase();
const fresh = rows.filter((r) => status(r) === 'QUEUE').sort((a, b) => a.row_number - b.row_number);
// A claimed row is skipped while it could still belong to a live run, and picked up once
// it is stale: there is no way to ask n8n whether an execution is alive, so the row's own
// UPDATE_DATE is the observable, and every phase writes it as it goes. Four hours is the
// window, which is longer than any review is waited on and shorter than a shift.
const STALE_CLAIM_HOURS = 4;
const resumable = rows
  .filter((r) => {
    if (status(r) !== 'IN_PROGRESS' || String(r.ARTICLE_STATUS || '').trim().toUpperCase() === 'CANCELLED') return false;
    const claimedAt = Date.parse(r.UPDATE_DATE || '');
    return isFinite(claimedAt) && (Date.now() - claimedAt) / 3600000 >= STALE_CLAIM_HOURS;
  })
  .sort((a, b) => a.row_number - b.row_number);
const row = fresh[0] || resumable[0];
if (!row) {
  console.log('article_queue holds nothing actionable (' + rows.length + ' rows read)');
  return [];
}
if (!String(row.TOPIC || '').trim() && !String(row.DESCRIPTION || '').trim()) {
  throw new Error('article_queue row ' + row.row_number + ' has neither TOPIC nor DESCRIPTION');
}
return [{ json: { ...row, ARTICLE_ROUND: Number(row.ARTICLE_ROUND || 0), MAX_WORDS: Number(row.MAX_WORDS || 0) || 1200 } }];

// The row's categories, checked against the one list the blog has (datasets/blog_categories.json)
// before anything is drafted or committed. A category the blog does not define is a failure
// with a reason, not a post published under a new heading: the alternative is a taxonomy that
// grows one row at a time and cannot be found again.
//
// The list is fetched, not copied into this node, and an unreadable file fails the run rather
// than skipping the check -- a silent skip is how a validation becomes decoration.
const raw = $('download_blog_categories').first().json.output || '{}';
let known;
try {
  known = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/blog_categories.json is not valid JSON: ' + e.message);
}
const allowed = new Set((known.categories || []).map((c) => String(c).trim()));
if (!allowed.size) throw new Error('datasets/blog_categories.json declares no category');
const row = $('pick_candidate').first().json;
const declared = String(row.CATEGORIES || '').split(',').map((c) => c.trim()).filter(Boolean);
const unknown = declared.filter((c) => !allowed.has(c));
if (declared.length && unknown.length) {
  throw new Error('row ' + row.row_number + ' names categories the blog does not define: ' + unknown.join(', ') + ' (known: ' + [...allowed].join(', ') + ')');
}
const categories = declared.length ? declared : ['General'];
return [{ json: { ...row, CATEGORIES: categories.join(', ') } }];

// The next action for the entry, from the predicate in the design (D15). A run always
// carries a hero: either raster counts as one, so a row naming the portrait `image` keeps
// its own choice and a row naming neither gets the wide one, which is the frame a page
// wants. `REQUESTED_ASSETS` is that set, and it is the only copy of the rule: the publish gate
// and the commit path read this field rather than deriving the hero rule again.
// The phase is read off
// the stored state in two places - the article's own review state on the sheet and the
// per-asset rows here - so a resumed run reaches the same next action as an uninterrupted one
// instead of guessing at whichever field looks unfinished.
const row = $('validate_categories').first().json;
const assets = $input.all().map((i) => i.json);
const requested = (r) => {
  const list = String(r.ASSET_TYPES || '').split(',').map((s) => s.trim()).filter(Boolean);
  const hasHero = list.includes('image_wide') || list.includes('image');
  return hasHero ? list : ['image_wide', ...list];
};
const requestedAssets = requested(row);
const pending = requestedAssets.filter((type) => {
  const hit = assets.find((a) => String(a.ASSET_TYPE || '') === type);
  return !hit || String(hit.STATUS || '').toUpperCase() !== 'APPROVED';
});
const article = String(row.ARTICLE_STATUS || '').trim().toUpperCase();
const phase = article === 'APPROVED' ? (pending.length ? 'assets' : 'publish') : 'draft';
console.log('row ' + row.row_number + ' -> ' + phase + ' (pending: ' + (pending.join(',') || 'none') + ')');
return [{ json: { ...row, PHASE: phase, PENDING_ASSETS: pending.join(','),
  REQUESTED_ASSETS: requestedAssets.join(',') } }];

// One item out of either branch, carrying the fetched text and whether it was used.
//
// The flag is set here and never read off the failing node's own output: a non-AI node with
// continueRegularOutput forwards its input unchanged, so `$json.error` is absent and a branch
// on it would take the success path. What is read is whether the download ran and what it
// returned, which this node can see either way.
const row = $('select_article_to_queue').first().json;
const link = String(row.LINK || '').trim();
let content = '';
if ($('download_content').isExecuted) {
  const out = $('download_content').first().json || {};
  content = String(typeof out.data === 'string' ? out.data : out.data || '').trim().slice(0, 60000);
}
const used = content.length > 0;
if (link && !used) console.log('link not used: ' + link);
return [{ json: { ...row, LINK_USED: used, LINK_TEXT: content } }];

// The slug, frozen at the first draft: a retry that changes the title must not rename a
// committed file or move the URL, so the row keeps the slug the first draft produced and a
// retry reuses it (design D11). The commit disambiguates it against the posts directory; the
// draft does not pay for that call.
const slugify = (title) => String(title || '')
  .toLowerCase()
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .split('-')
  .filter(Boolean)
  .slice(0, 8)
  .join('-');
const row = $('select_article_to_queue').first().json;
const title = String($('execute_article_creator').first().json.title || '').trim();
const slug = slugify(row.ARTICLE_TITLE) || slugify(title);
if (!title) throw new Error('the draft came back without a title');
if (!slug) throw new Error('no title to derive a slug from');
return [{ json: { ...row, DRAFT_TITLE: title, SLUG: slug } }];

// The draft reaches Slack as a file: a sendAndWait section truncates around 3000 characters
// and a 1200-word draft is several times that. The binary is built the way LinkedIn Image
// Creator's convert_image builds its png - one Buffer, the shape the Slack file upload reads.
const text = String($('execute_article_creator').first().json.text || '');
if (!text.trim()) throw new Error('the draft is empty; refusing to upload it');
const title = String($('derive_slug').first().json.DRAFT_TITLE || 'draft');
return [{
  json: { ...$('select_article_to_queue').first().json, DRAFT_TITLE: title, SLUG: $('derive_slug').first().json.SLUG, BYTES: Buffer.byteLength(text) },
  binary: { data: { mimeType: 'text/markdown', fileName: title + '.md', fileExtension: 'md', data: Buffer.from(text, 'utf8') } },
}];

// One item per asset the studio answered with. The run STATUS is deliberately not what is
// branched on: it is PARTIAL whenever any requested type is unavailable, so an unavailable
// type would take the whole set with it. Each asset's own STATUS is the decision, and a type
// the registry does not declare arrives here as an asset carrying its reason.
//
// Every response item is read, not the first: the studio answers with one item per asset
// branch because its own merge runs once per branch, so a two-type request arrives as two
// items carrying one asset each. Reading only the first of them is how the svg was
// authored, rendered and then dropped -- the asset rows never saw it and the publish gate found it
// MISSING (execution 13705, 2026-10-17).
const responses = $input.all().map((i) => i.json || {});
const resp = responses[0] || {};
const row = $('select_article_to_queue').first().json;
const assets = responses.flatMap((r) => (Array.isArray(r.ASSETS) ? r.ASSETS : []));
if (!assets.length) throw new Error('the studio returned no asset at all (runs ' + responses.map((r) => r.RUN_ID || '?').join(',') + ', status ' + (resp.STATUS || '?') + ')');
return assets.map((a) => ({
  json: {
    ...row,
    ROUND: Number(row.ARTICLE_ROUND || 0) + 1,
    RUN_ID: resp.RUN_ID || '',
    SESSION_ID: resp.SESSION_ID || '',
    ASSET_TYPE: a.ASSET_TYPE || '',
    ASSET_STATUS: a.STATUS || '',
    ERROR: a.ERROR || '',
    CONTENT_TYPE: a.CONTENT_TYPE || '',
    FORMAT: a.FORMAT || '',
    S3_KEY: a.S3_KEY || '',
    S3_BYTES: a.S3_BYTES || 0,
    IMAGE: a.IMAGE || '',
  },
}));

// The raster type carries its own bytes as a data URL, because they were made inside n8n and
// no store can fetch them. This is the only asset byte an article run carries, and it is why
// the hero previews in Slack without a bucket round trip.
const a = $('split_assets').first().json;
const url = String(a.IMAGE || '');
const comma = url.indexOf(',');
if (comma < 0) throw new Error('asset ' + a.ASSET_TYPE + ' carries no usable data URL');
const meta = url.slice(0, comma);
const data = Buffer.from(url.slice(comma + 1), 'base64');
const mime = (meta.match(/data:([^;]+)/) || [])[1] || a.CONTENT_TYPE || 'application/octet-stream';
const ext = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif' }[mime] || a.FORMAT || 'bin';
return [{
  json: { ...a, ASSET_MIME: mime, ASSET_EXT: ext, BYTES: data.length },
  binary: { data: { mimeType: mime, fileName: a.ASSET_TYPE + '.' + ext, fileExtension: ext, data } },
}];

// The signed URL the temp-bucket server answered with. The answer is split into key=value
// pairs the way a caller reads it rather than matched as prose, and a failure (a line
// beginning ERROR:) is raised here so the run reports it instead of uploading something else.
const resp = $input.first().json || {};
const content = resp.result && resp.result.content;
const text = content && content[0] && content[0].text;
if (typeof text !== 'string') throw new Error('the temp-bucket server answered no text');
if (text.indexOf('ERROR:') === 0) throw new Error(text.slice(0, 500));
const pairs = {};
for (const part of text.trim().split(/\s+/)) {
  const eq = part.indexOf('=');
  if (eq > 0) pairs[part.slice(0, eq)] = part.slice(eq + 1);
}
if (!pairs.url) throw new Error('no signed url in: ' + text.slice(0, 300));
const a = $('split_assets').first().json;
const mime = pairs['content-type'] || a.CONTENT_TYPE || 'application/octet-stream';
const ext = (mime.split('/')[1] || a.FORMAT || 'bin').replace('jpeg', 'jpg');
return [{ json: { ...a, SIGNED_URL: pairs.url, ASSET_MIME: mime, ASSET_EXT: ext, S3_BYTES: Number(pairs.bytes || a.S3_BYTES || 0) } }];

// Every requested type approved and none left in review: only then is there one commit.
//
// The check reads the stored rows rather than this run's history, so a resumed run that
// approved two of three assets earlier still publishes once the third clears. A cancelled
// asset keeps the article from committing, which is the deliberate direction: the run reports
// instead of publishing a post that is missing a picture it asked for.
// The set comes from the selector, which derived it once and runs on every path. A second
// derivation here is how a gate ends up prepending a type the selector never asked for, which
// blocks every run forever.
const effective = String($('select_article_to_queue').first().json.REQUESTED_ASSETS || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);
const rows = $('read_asset_rows').all().map((i) => i.json);
const statusOf = (type) => {
  const row = rows.find((r) => String(r.ASSET_TYPE || '') === type);
  return row ? String(row.STATUS || '').toUpperCase() : 'MISSING';
};
const blocking = effective.filter((type) => !['APPROVED', 'COMMITTED'].includes(statusOf(type)));
// The verdict is data and the branch on it is the next node: returning nothing here is how a
// blocked publish ended the execution as `success`, with no commit and no notice at all
// (execution 13705, 2026-10-17 -- the svg had never reached the asset rows).
const report = blocking.map((t) => t + '=' + statusOf(t)).join(', ');
if (blocking.length) console.log('not committing: ' + report);
return [{ json: {
  ...$('select_article_to_queue').first().json,
  ASSET_ROWS: effective.map((type) => rows.find((r) => String(r.ASSET_TYPE || '') === type)),
  BLOCKED: blocking.length > 0,
  BLOCKING: report || 'none',
} }];

// The frozen slug, unless the repository already carries a post with it. Nothing is
// committed before this point, so a disambiguated slug is still the one that is frozen.
const row = $('read_draft_for_publish').first().json;
const slug = String(row.SLUG || '').trim();
if (!slug) throw new Error('the draft row carries no slug; the draft was stored before this field existed');
const listing = $input.first().json;
const taken = new Set((Array.isArray(listing) ? listing : []).map((f) => String(f.name || '')));
let final = slug;
let n = 2;
while (taken.has(final + '.md') && n < 50) final = slug + '-' + n++;
if (final !== slug) console.log('slug ' + slug + ' is taken; using ' + final);
return [{ json: { ...row, SLUG: final } }];

// One item per file to commit: the article, then each approved asset. Front matter is
// composed here rather than asked of the model (D5), a marker is replaced in place, and a
// requested type whose marker the draft omitted is placed after the opening section instead
// of being dropped - one live draft in three answered image,svg with the image marker only.
// Only the entry's requested types are committed: a row for anything else is a leftover
// from an earlier request, and committing it adds an image no marker references.
const row = $('disambiguate_slug').first().json;
const draft = $('read_draft_for_publish').first().json;
const slug = row.SLUG;
const text = String(draft.ARTICLE_TEXT || '');
const title = String(draft.TITLE || '').trim();
if (!text.trim()) throw new Error('the stored draft is empty; refusing to commit');
if (!title.trim()) throw new Error('the stored draft has no title');

const categories = String($('select_article_to_queue').first().json.CATEGORIES || 'General')
  .split(',').map((s) => s.trim()).filter(Boolean);
const now = new Date();
const iso = now.toISOString();
const day = iso.slice(0, 10);
const front = ['---', 'date: ' + day, 'authors: [alvsanand]', 'categories: [' + categories.join(', ') + ']', '---', ''].join('\n');

const requestedTypes = String($('select_article_to_queue').first().json.REQUESTED_ASSETS || '')
  .split(',').map((s) => s.trim()).filter(Boolean);
const rows = $('read_asset_rows_for_publish').all().map((i) => i.json);
const stale = rows.map((a) => String(a.ASSET_TYPE || '')).filter((type) => !requestedTypes.includes(type));
if (stale.length) console.log('not committing, not requested by this entry: ' + stale.join(', '));
const assets = rows.filter((a) => requestedTypes.includes(String(a.ASSET_TYPE || ''))).map((a) => ({
  type: String(a.ASSET_TYPE || ''),
  ext: (String(a.CONTENT_TYPE || '').split('/')[1] || 'png').replace('jpeg', 'jpg'),
  alt: (title + ' - ' + String(a.ASSET_TYPE || '').replace(/_/g, ' ')).slice(0, 120),
}));
const pathOf = (a) => 'docs/img/' + slug + '-' + a.type + '.' + a.ext;

let body = text.replace(/^#\s+.*\n?/, '').trim();
const missing = [];
for (const a of assets) {
  const marker = new RegExp('<!--\\s*asset:' + a.type + '\\s*-->', 'g');
  const reference = '![' + a.alt + '](/' + pathOf(a) + '){ width="80%" }';
  if (marker.test(body)) body = body.replace(marker, reference);
  else missing.push(a.type);
}
if (missing.length) {
  const lines = body.split('\n');
  const heading = lines.findIndex((l, i) => i > 0 && l.startsWith('## '));
  const at = heading === -1 ? lines.length : heading;
  lines.splice(at, 0, '', ...missing.map((type) => {
    const a = assets.find((x) => x.type === type);
    return '![' + a.alt + '](/' + pathOf(a) + '){ width="80%" }';
  }), '');
  body = lines.join('\n');
  console.log('placed without a marker: ' + missing.join(', '));
}

const files = [{
  PATH: 'docs/blog/posts/' + day.slice(0, 4) + day.slice(5, 7) + '-' + slug + '.md',
  TEXT: front + '# ' + title + '\n\n' + body + '\n',
  BINARY: false,
}];
for (const a of assets) files.push({ PATH: pathOf(a), ASSET_TYPE: a.type, BINARY: true });

return files.map((f) => ({
  json: {
    ...$('select_article_to_queue').first().json,
    SLUG: slug,
    DRAFT_TITLE: title,
    PUBLISHED_URL: 'https://alvsanand.com/blog/' + day.slice(0, 4) + '/' + day.slice(5, 7) + '/' + day.slice(8, 10) + '/' + slug + '/',
    FILE_PATH: f.PATH,
    FILE_TEXT: f.TEXT || '',
    FILE_IS_BINARY: f.BINARY,
    ASSET_TYPE: f.ASSET_TYPE || '',
    COMMIT_MESSAGE: 'docs(blog): ' + title,
  },
}));

// What each approved asset's bytes are, and where they have to come from.
//
// A raster hero has no durable handle of its own - the studio made its bytes inside n8n and
// keeps no copy - so the review stored them on its asset row, which is the same shape
// TemporalFiles uses for the same reason. An agent-authored asset does have one: its S3 key,
// which the utils server signs a URL for on demand. A resumed commit run therefore still has
// every byte it needs, which is what makes the persistence in section 4 worth anything.
const rows = $('read_asset_rows_for_publish').all().map((i) => i.json);
const rowOf = (type) => rows.find((r) => String(r.ASSET_TYPE || '') === type) || {};
const files = $('build_commit_files').all().map((i) => i.json).filter((j) => j.FILE_IS_BINARY);
return files.map((j) => {
  const row = rowOf(j.ASSET_TYPE);
  const local = String(row.DATA_BASE64 || '');
  if (local) {
    return { json: { ...j, FILE_BASE64: local, FILE_BYTES: Buffer.from(local, 'base64').length, NEEDS_FETCH: false } };
  }
  if (!row.S3_KEY) throw new Error('asset ' + j.ASSET_TYPE + ' has neither stored bytes nor an object key');
  return { json: { ...j, FILE_BASE64: '', NEEDS_FETCH: true, S3_KEY: row.S3_KEY } };
});

// The signed URL for this asset, read the same way the review path reads it.
const resp = $input.first().json || {};
const content = resp.result && resp.result.content;
const text = content && content[0] && content[0].text;
if (typeof text !== 'string') throw new Error('the temp-bucket server answered no text');
if (text.indexOf('ERROR:') === 0) throw new Error(text.slice(0, 500));
const pairs = {};
for (const part of text.trim().split(/\s+/)) {
  const eq = part.indexOf('=');
  if (eq > 0) pairs[part.slice(0, eq)] = part.slice(eq + 1);
}
if (!pairs.url) throw new Error('no signed url in: ' + text.slice(0, 300));
return [{ json: { ...$('plan_asset_uploads').first().json, SIGNED_URL: pairs.url, SIGNED_BYTES: Number(pairs.bytes || 0) } }];

// The fetched bytes, as base64 for the blob API, carrying the same fields the local branch
// already had so the two paths converge on one shape.
const j = $('plan_asset_uploads').all().find((i) => i.json.S3_KEY === $('asset_publish_url').first().json.S3_KEY).json;
const bin = ($input.first().binary || {}).data;
if (!bin) throw new Error('the signed url served no bytes for ' + j.ASSET_TYPE);
return [{ json: { ...j, FILE_BASE64: Buffer.from(bin.data).toString('base64'), FILE_BYTES: bin.data.length, NEEDS_FETCH: false } }];

// The tree the commit carries: every text file inline (the Trees API takes utf-8 content)
// and every asset as the blob sha it just got. The sha-to-path pairing is asserted against the
// byte length each blob reports, so a mis-order fails loudly rather than committing a picture
// under the article's name.
const files = $('build_commit_files').all().map((i) => i.json);
const blobs = files.filter((f) => f.FILE_IS_BINARY);
const answers = $('create_blobs').all().map((i) => i.json);
if (answers.length !== blobs.length) {
  throw new Error('GitHub answered ' + answers.length + ' blobs for ' + blobs.length + ' assets');
}
const expected = $('plan_asset_uploads').all().map((i) => i.json.FILE_BYTES);
const entries = files.map((f) => ({ path: f.FILE_PATH, mode: '100644', type: 'blob' }));
blobs.forEach((f, i) => {
  const answer = answers[i] || {};
  if (!answer.sha) throw new Error('GitHub answered no sha for ' + f.FILE_PATH);
  if (Number(answer.size) && Number(answer.size) !== Number(expected[i])) {
    throw new Error('blob ' + i + ' is ' + answer.size + ' bytes against an expected ' + expected[i] + '; refusing to guess which file it is');
  }
  const at = entries.findIndex((e) => e.path === f.FILE_PATH);
  entries[at].sha = answer.sha;
});
files.filter((f) => !f.FILE_IS_BINARY).forEach((f) => {
  const at = entries.findIndex((e) => e.path === f.FILE_PATH);
  entries[at].content = f.FILE_TEXT;
});
return [{ json: { ...$('build_commit_files').first().json, TREE_ENTRIES: entries, FILE_COUNT: files.length } }];

// The retry is only worth anything if the second PATCH also failed: a first failure means the
// branch moved, and the tree and commit above were rebuilt on the branch's new head. A second
// failure is reported rather than looped, which is what the spec asks for.
const resp = $input.first().json || {};
if (resp.error || resp.message) {
  throw new Error('the commit could not be fast-forwarded twice: ' + String(resp.message || resp.error).slice(0, 300));
}
return [{ json: { ...$('collect_tree_entries').first().json, COMMIT_SHA: resp.sha || ($('create_commit_again').isExecuted ? $('create_commit_again').item.json.sha : $('create_commit').item.json.sha) } }];

// One item per committed asset, so its row records where it landed. The paths come from the
// commit's own file list rather than from a second derivation.
return $('build_commit_files').all()
  .map((i) => i.json)
  .filter((j) => j.FILE_IS_BINARY)
  .map((j) => ({ json: { ENTRY_ID: j.ENTRY_ID, ASSET_TYPE: j.ASSET_TYPE, PATH: j.FILE_PATH } }));

// One studio call per pending type. The studio answers with one asset per response item and
// a sub-workflow's response is its last node's LAST run, so a two-type request reaches the
// caller as a single asset -- the other branch's item is dropped inside n8n. Measured
// 2026-10-17: the studio authored and rendered both (execution 13722, `svg_wide` stored at
// `visual-studio/13722-svg_wide.svg`) and the caller received one asset (execution 13720),
// so the publish gate reported `svg_wide=MISSING`. One call per type keeps every asset:
// each call has one branch, one response item, and one asset in it.
const row = $('select_article_to_queue').first().json;
const draft = $('read_draft_for_assets').first().json;
const pending = String(row.PENDING_ASSETS || row.ASSET_TYPES || 'image_wide')
  .split(',').map((s) => s.trim()).filter(Boolean);
if (!pending.length) throw new Error('no asset type is pending for row ' + row.row_number);
return pending.map((type) => ({ json: {
  ...row,
  ...draft,
  ASSET_TYPE: type,
  ROUND: Number(row.ARTICLE_ROUND || 0) + 1,
} }));

// The one entry this run works on (D8), chosen from the sheet alone so the asset read below
// can be filtered on it. QUEUE first, then the oldest mid-flight claim: a run that died while
// Slack waited is picked up before a new row is started, so a stuck entry cannot starve behind
// fresh work. Half-finished work is never inferred from whichever field looks untouched - that
// is what select_article_to_queue decides next, from the asset rows.
const rows = $input.all()
  .map((i) => ({ ...i.json, row_number: Number(i.json.row_number || 0) }))
  .filter((r) => r.row_number && String(r.ENTRY_ID || '').trim());
const status = (r) => String(r.STATUS || '').trim().toUpperCase();
const fresh = rows.filter((r) => status(r) === 'QUEUE').sort((a, b) => a.row_number - b.row_number);
// A claimed row is skipped while it could still belong to a live run, and picked up once
// it is stale: there is no way to ask n8n whether an execution is alive, so the row's own
// UPDATE_DATE is the observable, and every phase writes it as it goes. Four hours is the
// window, which is longer than any review is waited on and shorter than a shift.
const STALE_CLAIM_HOURS = 4;
const resumable = rows
  .filter((r) => {
    if (status(r) !== 'IN_PROGRESS' || String(r.ARTICLE_STATUS || '').trim().toUpperCase() === 'CANCELLED') return false;
    const claimedAt = Date.parse(r.UPDATE_DATE || '');
    return isFinite(claimedAt) && (Date.now() - claimedAt) / 3600000 >= STALE_CLAIM_HOURS;
  })
  .sort((a, b) => a.row_number - b.row_number);
const row = fresh[0] || resumable[0];
if (!row) {
  console.log('article_queue holds nothing actionable (' + rows.length + ' rows read)');
  return [];
}
if (!String(row.TOPIC || '').trim() && !String(row.DESCRIPTION || '').trim()) {
  throw new Error('article_queue row ' + row.row_number + ' has neither TOPIC nor DESCRIPTION');
}
return [{ json: { ...row, ARTICLE_ROUND: Number(row.ARTICLE_ROUND || 0), MAX_WORDS: Number(row.MAX_WORDS || 0) || 1200 } }];

// The row's categories, checked against the one list the blog has (datasets/blog_categories.json)
// before anything is drafted or committed. A category the blog does not define is a failure
// with a reason, not a post published under a new heading: the alternative is a taxonomy that
// grows one row at a time and cannot be found again.
//
// The list is fetched, not copied into this node, and an unreadable file fails the run rather
// than skipping the check -- a silent skip is how a validation becomes decoration.
const raw = $('download_blog_categories').first().json.output || '{}';
let known;
try {
  known = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/blog_categories.json is not valid JSON: ' + e.message);
}
const allowed = new Set((known.categories || []).map((c) => String(c).trim()));
if (!allowed.size) throw new Error('datasets/blog_categories.json declares no category');
const row = $('pick_candidate').first().json;
const declared = String(row.CATEGORIES || '').split(',').map((c) => c.trim()).filter(Boolean);
const unknown = declared.filter((c) => !allowed.has(c));
if (declared.length && unknown.length) {
  throw new Error('row ' + row.row_number + ' names categories the blog does not define: ' + unknown.join(', ') + ' (known: ' + [...allowed].join(', ') + ')');
}
const categories = declared.length ? declared : ['General'];
return [{ json: { ...row, CATEGORIES: categories.join(', ') } }];

// The next action for the entry, from the predicate in the design (D15). A run always
// carries a hero: either raster counts as one, so a row naming the portrait `image` keeps
// its own choice and a row naming neither gets the wide one, which is the frame a page
// wants. `REQUESTED_ASSETS` is that set, and it is the only copy of the rule: the publish gate
// and the commit path read this field rather than deriving the hero rule again.
// The phase is read off
// the stored state in two places - the article's own review state on the sheet and the
// per-asset rows here - so a resumed run reaches the same next action as an uninterrupted one
// instead of guessing at whichever field looks unfinished.
const row = $('validate_categories').first().json;
const assets = $input.all().map((i) => i.json);
const requested = (r) => {
  const list = String(r.ASSET_TYPES || '').split(',').map((s) => s.trim()).filter(Boolean);
  const hasHero = list.includes('image_wide') || list.includes('image');
  return hasHero ? list : ['image_wide', ...list];
};
const requestedAssets = requested(row);
const pending = requestedAssets.filter((type) => {
  const hit = assets.find((a) => String(a.ASSET_TYPE || '') === type);
  return !hit || String(hit.STATUS || '').toUpperCase() !== 'APPROVED';
});
const article = String(row.ARTICLE_STATUS || '').trim().toUpperCase();
const phase = article === 'APPROVED' ? (pending.length ? 'assets' : 'publish') : 'draft';
console.log('row ' + row.row_number + ' -> ' + phase + ' (pending: ' + (pending.join(',') || 'none') + ')');
return [{ json: { ...row, PHASE: phase, PENDING_ASSETS: pending.join(','),
  REQUESTED_ASSETS: requestedAssets.join(',') } }];

// One item out of either branch, carrying the fetched text and whether it was used.
//
// The flag is set here and never read off the failing node's own output: a non-AI node with
// continueRegularOutput forwards its input unchanged, so `$json.error` is absent and a branch
// on it would take the success path. What is read is whether the download ran and what it
// returned, which this node can see either way.
const row = $('select_article_to_queue').first().json;
const link = String(row.LINK || '').trim();
let content = '';
if ($('download_content').isExecuted) {
  const out = $('download_content').first().json || {};
  content = String(typeof out.data === 'string' ? out.data : out.data || '').trim().slice(0, 60000);
}
const used = content.length > 0;
if (link && !used) console.log('link not used: ' + link);
return [{ json: { ...row, LINK_USED: used, LINK_TEXT: content } }];

// The slug, frozen at the first draft: a retry that changes the title must not rename a
// committed file or move the URL, so the row keeps the slug the first draft produced and a
// retry reuses it (design D11). The commit disambiguates it against the posts directory; the
// draft does not pay for that call.
const slugify = (title) => String(title || '')
  .toLowerCase()
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .split('-')
  .filter(Boolean)
  .slice(0, 8)
  .join('-');
const row = $('select_article_to_queue').first().json;
const title = String($('execute_article_creator').first().json.title || '').trim();
const slug = slugify(row.ARTICLE_TITLE) || slugify(title);
if (!title) throw new Error('the draft came back without a title');
if (!slug) throw new Error('no title to derive a slug from');
return [{ json: { ...row, DRAFT_TITLE: title, SLUG: slug } }];

// The draft reaches Slack as a file: a sendAndWait section truncates around 3000 characters
// and a 1200-word draft is several times that. The binary is built the way LinkedIn Image
// Creator's convert_image builds its png - one Buffer, the shape the Slack file upload reads.
const text = String($('execute_article_creator').first().json.text || '');
if (!text.trim()) throw new Error('the draft is empty; refusing to upload it');
const title = String($('derive_slug').first().json.DRAFT_TITLE || 'draft');
return [{
  json: { ...$('select_article_to_queue').first().json, DRAFT_TITLE: title, SLUG: $('derive_slug').first().json.SLUG, BYTES: Buffer.byteLength(text) },
  binary: { data: { mimeType: 'text/markdown', fileName: title + '.md', fileExtension: 'md', data: Buffer.from(text, 'utf8') } },
}];

// One item per asset the studio answered with. The run STATUS is deliberately not what is
// branched on: it is PARTIAL whenever any requested type is unavailable, so an unavailable
// type would take the whole set with it. Each asset's own STATUS is the decision, and a type
// the registry does not declare arrives here as an asset carrying its reason.
//
// Every response item is read, not the first: the studio answers with one item per asset
// branch because its own merge runs once per branch, so a two-type request arrives as two
// items carrying one asset each. Reading only the first of them is how the svg was
// authored, rendered and then dropped -- the asset rows never saw it and the publish gate found it
// MISSING (execution 13705, 2026-10-17).
const responses = $input.all().map((i) => i.json || {});
const resp = responses[0] || {};
const row = $('select_article_to_queue').first().json;
const assets = responses.flatMap((r) => (Array.isArray(r.ASSETS) ? r.ASSETS : []));
if (!assets.length) throw new Error('the studio returned no asset at all (runs ' + responses.map((r) => r.RUN_ID || '?').join(',') + ', status ' + (resp.STATUS || '?') + ')');
return assets.map((a) => ({
  json: {
    ...row,
    ROUND: Number(row.ARTICLE_ROUND || 0) + 1,
    RUN_ID: resp.RUN_ID || '',
    SESSION_ID: resp.SESSION_ID || '',
    ASSET_TYPE: a.ASSET_TYPE || '',
    ASSET_STATUS: a.STATUS || '',
    ERROR: a.ERROR || '',
    CONTENT_TYPE: a.CONTENT_TYPE || '',
    FORMAT: a.FORMAT || '',
    S3_KEY: a.S3_KEY || '',
    S3_BYTES: a.S3_BYTES || 0,
    IMAGE: a.IMAGE || '',
  },
}));

// The raster type carries its own bytes as a data URL, because they were made inside n8n and
// no store can fetch them. This is the only asset byte an article run carries, and it is why
// the hero previews in Slack without a bucket round trip.
const a = $('split_assets').first().json;
const url = String(a.IMAGE || '');
const comma = url.indexOf(',');
if (comma < 0) throw new Error('asset ' + a.ASSET_TYPE + ' carries no usable data URL');
const meta = url.slice(0, comma);
const data = Buffer.from(url.slice(comma + 1), 'base64');
const mime = (meta.match(/data:([^;]+)/) || [])[1] || a.CONTENT_TYPE || 'application/octet-stream';
const ext = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif' }[mime] || a.FORMAT || 'bin';
return [{
  json: { ...a, ASSET_MIME: mime, ASSET_EXT: ext, BYTES: data.length },
  binary: { data: { mimeType: mime, fileName: a.ASSET_TYPE + '.' + ext, fileExtension: ext, data } },
}];

// The signed URL the temp-bucket server answered with. The answer is split into key=value
// pairs the way a caller reads it rather than matched as prose, and a failure (a line
// beginning ERROR:) is raised here so the run reports it instead of uploading something else.
const resp = $input.first().json || {};
const content = resp.result && resp.result.content;
const text = content && content[0] && content[0].text;
if (typeof text !== 'string') throw new Error('the temp-bucket server answered no text');
if (text.indexOf('ERROR:') === 0) throw new Error(text.slice(0, 500));
const pairs = {};
for (const part of text.trim().split(/\s+/)) {
  const eq = part.indexOf('=');
  if (eq > 0) pairs[part.slice(0, eq)] = part.slice(eq + 1);
}
if (!pairs.url) throw new Error('no signed url in: ' + text.slice(0, 300));
const a = $('split_assets').first().json;
const mime = pairs['content-type'] || a.CONTENT_TYPE || 'application/octet-stream';
const ext = (mime.split('/')[1] || a.FORMAT || 'bin').replace('jpeg', 'jpg');
return [{ json: { ...a, SIGNED_URL: pairs.url, ASSET_MIME: mime, ASSET_EXT: ext, S3_BYTES: Number(pairs.bytes || a.S3_BYTES || 0) } }];

// Every requested type approved and none left in review: only then is there one commit.
//
// The check reads the stored rows rather than this run's history, so a resumed run that
// approved two of three assets earlier still publishes once the third clears. A cancelled
// asset keeps the article from committing, which is the deliberate direction: the run reports
// instead of publishing a post that is missing a picture it asked for.
// The set comes from the selector, which derived it once and runs on every path. A second
// derivation here is how a gate ends up prepending a type the selector never asked for, which
// blocks every run forever.
const effective = String($('select_article_to_queue').first().json.REQUESTED_ASSETS || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);
const rows = $('read_asset_rows').all().map((i) => i.json);
const statusOf = (type) => {
  const row = rows.find((r) => String(r.ASSET_TYPE || '') === type);
  return row ? String(row.STATUS || '').toUpperCase() : 'MISSING';
};
const blocking = effective.filter((type) => !['APPROVED', 'COMMITTED'].includes(statusOf(type)));
// The verdict is data and the branch on it is the next node: returning nothing here is how a
// blocked publish ended the execution as `success`, with no commit and no notice at all
// (execution 13705, 2026-10-17 -- the svg had never reached the asset rows).
const report = blocking.map((t) => t + '=' + statusOf(t)).join(', ');
if (blocking.length) console.log('not committing: ' + report);
return [{ json: {
  ...$('select_article_to_queue').first().json,
  ASSET_ROWS: effective.map((type) => rows.find((r) => String(r.ASSET_TYPE || '') === type)),
  BLOCKED: blocking.length > 0,
  BLOCKING: report || 'none',
} }];

// The frozen slug, unless the repository already carries a post with it. Nothing is
// committed before this point, so a disambiguated slug is still the one that is frozen.
const row = $('read_draft_for_publish').first().json;
const slug = String(row.SLUG || '').trim();
if (!slug) throw new Error('the draft row carries no slug; the draft was stored before this field existed');
const listing = $input.first().json;
const taken = new Set((Array.isArray(listing) ? listing : []).map((f) => String(f.name || '')));
let final = slug;
let n = 2;
while (taken.has(final + '.md') && n < 50) final = slug + '-' + n++;
if (final !== slug) console.log('slug ' + slug + ' is taken; using ' + final);
return [{ json: { ...row, SLUG: final } }];

// One item per file to commit: the article, then each approved asset. Front matter is
// composed here rather than asked of the model (D5), a marker is replaced in place, and a
// requested type whose marker the draft omitted is placed after the opening section instead
// of being dropped - one live draft in three answered image,svg with the image marker only.
// Only the entry's requested types are committed: a row for anything else is a leftover
// from an earlier request, and committing it adds an image no marker references.
const row = $('disambiguate_slug').first().json;
const draft = $('read_draft_for_publish').first().json;
const slug = row.SLUG;
const text = String(draft.ARTICLE_TEXT || '');
const title = String(draft.TITLE || '').trim();
if (!text.trim()) throw new Error('the stored draft is empty; refusing to commit');
if (!title.trim()) throw new Error('the stored draft has no title');

const categories = String($('select_article_to_queue').first().json.CATEGORIES || 'General')
  .split(',').map((s) => s.trim()).filter(Boolean);
const now = new Date();
const iso = now.toISOString();
const day = iso.slice(0, 10);
const front = ['---', 'date: ' + day, 'authors: [alvsanand]', 'categories: [' + categories.join(', ') + ']', '---', ''].join('\n');

const requestedTypes = String($('select_article_to_queue').first().json.REQUESTED_ASSETS || '')
  .split(',').map((s) => s.trim()).filter(Boolean);
const rows = $('read_asset_rows_for_publish').all().map((i) => i.json);
const stale = rows.map((a) => String(a.ASSET_TYPE || '')).filter((type) => !requestedTypes.includes(type));
if (stale.length) console.log('not committing, not requested by this entry: ' + stale.join(', '));
const assets = rows.filter((a) => requestedTypes.includes(String(a.ASSET_TYPE || ''))).map((a) => ({
  type: String(a.ASSET_TYPE || ''),
  ext: (String(a.CONTENT_TYPE || '').split('/')[1] || 'png').replace('jpeg', 'jpg'),
  alt: (title + ' - ' + String(a.ASSET_TYPE || '').replace(/_/g, ' ')).slice(0, 120),
}));
const pathOf = (a) => 'docs/img/' + slug + '-' + a.type + '.' + a.ext;

let body = text.replace(/^#\s+.*\n?/, '').trim();
const missing = [];
for (const a of assets) {
  const marker = new RegExp('<!--\\s*asset:' + a.type + '\\s*-->', 'g');
  const reference = '![' + a.alt + '](/' + pathOf(a) + '){ width="80%" }';
  if (marker.test(body)) body = body.replace(marker, reference);
  else missing.push(a.type);
}
if (missing.length) {
  const lines = body.split('\n');
  const heading = lines.findIndex((l, i) => i > 0 && l.startsWith('## '));
  const at = heading === -1 ? lines.length : heading;
  lines.splice(at, 0, '', ...missing.map((type) => {
    const a = assets.find((x) => x.type === type);
    return '![' + a.alt + '](/' + pathOf(a) + '){ width="80%" }';
  }), '');
  body = lines.join('\n');
  console.log('placed without a marker: ' + missing.join(', '));
}

const files = [{
  PATH: 'docs/blog/posts/' + day.slice(0, 4) + day.slice(5, 7) + '-' + slug + '.md',
  TEXT: front + '# ' + title + '\n\n' + body + '\n',
  BINARY: false,
}];
for (const a of assets) files.push({ PATH: pathOf(a), ASSET_TYPE: a.type, BINARY: true });

return files.map((f) => ({
  json: {
    ...$('select_article_to_queue').first().json,
    SLUG: slug,
    DRAFT_TITLE: title,
    PUBLISHED_URL: 'https://alvsanand.com/blog/' + day.slice(0, 4) + '/' + day.slice(5, 7) + '/' + day.slice(8, 10) + '/' + slug + '/',
    FILE_PATH: f.PATH,
    FILE_TEXT: f.TEXT || '',
    FILE_IS_BINARY: f.BINARY,
    ASSET_TYPE: f.ASSET_TYPE || '',
    COMMIT_MESSAGE: 'docs(blog): ' + title,
  },
}));

// What each approved asset's bytes are, and where they have to come from.
//
// A raster hero has no durable handle of its own - the studio made its bytes inside n8n and
// keeps no copy - so the review stored them on its asset row, which is the same shape
// TemporalFiles uses for the same reason. An agent-authored asset does have one: its S3 key,
// which the utils server signs a URL for on demand. A resumed commit run therefore still has
// every byte it needs, which is what makes the persistence in section 4 worth anything.
const rows = $('read_asset_rows_for_publish').all().map((i) => i.json);
const rowOf = (type) => rows.find((r) => String(r.ASSET_TYPE || '') === type) || {};
const files = $('build_commit_files').all().map((i) => i.json).filter((j) => j.FILE_IS_BINARY);
return files.map((j) => {
  const row = rowOf(j.ASSET_TYPE);
  const local = String(row.DATA_BASE64 || '');
  if (local) {
    return { json: { ...j, FILE_BASE64: local, FILE_BYTES: Buffer.from(local, 'base64').length, NEEDS_FETCH: false } };
  }
  if (!row.S3_KEY) throw new Error('asset ' + j.ASSET_TYPE + ' has neither stored bytes nor an object key');
  return { json: { ...j, FILE_BASE64: '', NEEDS_FETCH: true, S3_KEY: row.S3_KEY } };
});

// The signed URL for this asset, read the same way the review path reads it.
const resp = $input.first().json || {};
const content = resp.result && resp.result.content;
const text = content && content[0] && content[0].text;
if (typeof text !== 'string') throw new Error('the temp-bucket server answered no text');
if (text.indexOf('ERROR:') === 0) throw new Error(text.slice(0, 500));
const pairs = {};
for (const part of text.trim().split(/\s+/)) {
  const eq = part.indexOf('=');
  if (eq > 0) pairs[part.slice(0, eq)] = part.slice(eq + 1);
}
if (!pairs.url) throw new Error('no signed url in: ' + text.slice(0, 300));
return [{ json: { ...$('plan_asset_uploads').first().json, SIGNED_URL: pairs.url, SIGNED_BYTES: Number(pairs.bytes || 0) } }];

// The fetched bytes, as base64 for the blob API, carrying the same fields the local branch
// already had so the two paths converge on one shape.
const j = $('plan_asset_uploads').all().find((i) => i.json.S3_KEY === $('asset_publish_url').first().json.S3_KEY).json;
const bin = ($input.first().binary || {}).data;
if (!bin) throw new Error('the signed url served no bytes for ' + j.ASSET_TYPE);
return [{ json: { ...j, FILE_BASE64: Buffer.from(bin.data).toString('base64'), FILE_BYTES: bin.data.length, NEEDS_FETCH: false } }];

// The tree the commit carries: every text file inline (the Trees API takes utf-8 content)
// and every asset as the blob sha it just got. The sha-to-path pairing is asserted against the
// byte length each blob reports, so a mis-order fails loudly rather than committing a picture
// under the article's name.
const files = $('build_commit_files').all().map((i) => i.json);
const blobs = files.filter((f) => f.FILE_IS_BINARY);
const answers = $('create_blobs').all().map((i) => i.json);
if (answers.length !== blobs.length) {
  throw new Error('GitHub answered ' + answers.length + ' blobs for ' + blobs.length + ' assets');
}
const expected = $('plan_asset_uploads').all().map((i) => i.json.FILE_BYTES);
const entries = files.map((f) => ({ path: f.FILE_PATH, mode: '100644', type: 'blob' }));
blobs.forEach((f, i) => {
  const answer = answers[i] || {};
  if (!answer.sha) throw new Error('GitHub answered no sha for ' + f.FILE_PATH);
  if (Number(answer.size) && Number(answer.size) !== Number(expected[i])) {
    throw new Error('blob ' + i + ' is ' + answer.size + ' bytes against an expected ' + expected[i] + '; refusing to guess which file it is');
  }
  const at = entries.findIndex((e) => e.path === f.FILE_PATH);
  entries[at].sha = answer.sha;
});
files.filter((f) => !f.FILE_IS_BINARY).forEach((f) => {
  const at = entries.findIndex((e) => e.path === f.FILE_PATH);
  entries[at].content = f.FILE_TEXT;
});
return [{ json: { ...$('build_commit_files').first().json, TREE_ENTRIES: entries, FILE_COUNT: files.length } }];

// The retry is only worth anything if the second PATCH also failed: a first failure means the
// branch moved, and the tree and commit above were rebuilt on the branch's new head. A second
// failure is reported rather than looped, which is what the spec asks for.
const resp = $input.first().json || {};
if (resp.error || resp.message) {
  throw new Error('the commit could not be fast-forwarded twice: ' + String(resp.message || resp.error).slice(0, 300));
}
return [{ json: { ...$('collect_tree_entries').first().json, COMMIT_SHA: resp.sha || ($('create_commit_again').isExecuted ? $('create_commit_again').item.json.sha : $('create_commit').item.json.sha) } }];

// One item per committed asset, so its row records where it landed. The paths come from the
// commit's own file list rather than from a second derivation.
return $('build_commit_files').all()
  .map((i) => i.json)
  .filter((j) => j.FILE_IS_BINARY)
  .map((j) => ({ json: { ENTRY_ID: j.ENTRY_ID, ASSET_TYPE: j.ASSET_TYPE, PATH: j.FILE_PATH } }));

// One studio call per pending type. The studio answers with one asset per response item and
// a sub-workflow's response is its last node's LAST run, so a two-type request reaches the
// caller as a single asset -- the other branch's item is dropped inside n8n. Measured
// 2026-10-17: the studio authored and rendered both (execution 13722, `svg_wide` stored at
// `visual-studio/13722-svg_wide.svg`) and the caller received one asset (execution 13720),
// so the publish gate reported `svg_wide=MISSING`. One call per type keeps every asset:
// each call has one branch, one response item, and one asset in it.
const row = $('select_article_to_queue').first().json;
const draft = $('read_draft_for_assets').first().json;
const pending = String(row.PENDING_ASSETS || row.ASSET_TYPES || 'image_wide')
  .split(',').map((s) => s.trim()).filter(Boolean);
if (!pending.length) throw new Error('no asset type is pending for row ' + row.row_number);
return pending.map((type) => ({ json: {
  ...row,
  ...draft,
  ASSET_TYPE: type,
  ROUND: Number(row.ARTICLE_ROUND || 0) + 1,
} }));
